"use strict";(globalThis.webpackChunkdoqumentation=globalThis.webpackChunkdoqumentation||[]).push([[18313],{63540(i,e,a){a.r(e),a.d(e,{assets:()=>l,contentTitle:()=>s,default:()=>p,frontMatter:()=>r,metadata:()=>o,toc:()=>c});const o=JSON.parse('{"id":"learning/courses/practical-near-term-qc/introduction","title":"Introduction","description":"Un\'introduzione a un corso sulle applicazioni pratiche del calcolo quantistico.","source":"@site/i18n/it/docusaurus-plugin-content-docs/current/learning/courses/practical-near-term-qc/introduction.mdx","sourceDirName":"learning/courses/practical-near-term-qc","slug":"/learning/courses/practical-near-term-qc/introduction","permalink":"/learning/courses/practical-near-term-qc/introduction","draft":false,"unlisted":false,"editUrl":"https://github.com/JanLahmann/doQumentation/tree/main/docs/learning/courses/practical-near-term-qc/introduction.mdx","tags":[],"version":"current","frontMatter":{"description":"Un\'introduzione a un corso sulle applicazioni pratiche del calcolo quantistico.","notebook_path":"learning/courses/practical-near-term-qc/introduction.ipynb","sidebar_label":"Introduction","title":"Introduction"},"sidebar":"tutorialsSidebar","previous":{"title":"Overview","permalink":"/learning/courses/practical-near-term-qc/"},"next":{"title":"Panoramica","permalink":"/learning/courses/quantum-business-foundations/"}}');var n=a(74848),t=a(28453);const r={description:"Un'introduzione a un corso sulle applicazioni pratiche del calcolo quantistico.",notebook_path:"learning/courses/practical-near-term-qc/introduction.ipynb",sidebar_label:"Introduction",title:"Introduction"},s="Introduzione al calcolo quantistico pratico a breve termine {#introduction-to-practical-near-term-quantum-computing}",l={},c=[{value:"A cosa potrebbero servire i computer quantistici",id:"what-quantum-computers-might-be-useful-for",level:2},{value:"Utilit\xe0 e vantaggio quantistico a breve termine",id:"near-term-quantum-utility-and-advantage",level:2},{value:"Una breve introduzione alla teoria della complessit\xe0",id:"a-brief-foundation-in-complexity-theory",level:2},{value:"Dalla teoria della complessit\xe0 all&#39;evidenza pratica",id:"from-complexity-theory-to-practical-evidence",level:2},{value:"Aree applicative e casi di studio del corso",id:"application-areas-and-course-case-studies",level:2},{value:"Simulazione hamiltoniana",id:"hamiltonian-simulation",level:3},{value:"Ottimizzazione",id:"optimization",level:3},{value:"Machine learning quantistico",id:"quantum-machine-learning",level:3},{value:"Equazioni differenziali alle derivate parziali",id:"partial-differential-equations",level:3},{value:"Conclusione",id:"conclusion",level:2}];function u(i){const e={h1:"h1",h2:"h2",h3:"h3",header:"header",li:"li",p:"p",strong:"strong",ul:"ul",...(0,t.R)(),...i.components};return(0,n.jsxs)(n.Fragment,{children:["\n",(0,n.jsx)(e.header,{children:(0,n.jsx)(e.h1,{id:"introduction-to-practical-near-term-quantum-computing",children:"Introduzione al calcolo quantistico pratico a breve termine"})}),"\n",(0,n.jsx)(e.p,{children:"Fin da quando i computer quantistici sono stati proposti per la prima volta, pi\xf9 di quattro decenni fa, la domanda \xe8 stata: fino a dove questo nuovo approccio potrebbe spingere i limiti del calcolo? L'informatica teorica ci ha dato alcune risposte entusiasmanti. I computer quantistici potrebbero fattorizzare grandi numeri interi in modo drasticamente pi\xf9 veloce dei migliori metodi classici noti, accelerare la ricerca non strutturata e simulare i sistemi quantistici in modo pi\xf9 naturale. Tuttavia, molte di queste idee presupponevano un futuro computer quantistico fault-tolerant su larga scala."}),"\n",(0,n.jsx)(e.p,{children:"La tecnologia non ha ancora raggiunto tutti questi obiettivi teorici, ma sta migliorando rapidamente. Oggi i ricercatori possono usare i processori quantistici per esplorare problemi scientifici e industriali reali. In questo corso faremo esperienza pratica con alcune delle applicazioni pi\xf9 promettenti. Stimeremo le propriet\xe0 a bassa energia di un modello molecolare complesso, simuleremo la dinamica di una teoria di gauge su reticolo ed esploreremo come un problema di portafoglio finanziario possa essere mappato su un computer quantistico. Esamineremo anche aree pi\xf9 recenti in cui abbiamo appena iniziato a capire cosa potrebbero offrire i computer quantistici, tra cui il machine learning quantistico (QML) e gli approcci quantistici alle equazioni differenziali alle derivate parziali (PDE)."}),"\n",(0,n.jsx)(e.p,{children:"Molti degli esempi di questo corso sono abbastanza piccoli da poter essere risolti da un computer classico. \xc8 una scelta voluta. L'obiettivo \xe8 darti un'esperienza concreta dell'intero processo di utilizzo di un computer quantistico per affrontare un problema reale. Alcuni esempi rappresentano problemi per i quali il vantaggio quantistico potrebbe emergere su scale molto pi\xf9 grandi. In altri esempi usiamo un metodo semplificato, in modo che i dettagli implementativi non nascondano l'idea quantistica centrale."}),"\n",(0,n.jsx)(e.p,{children:"Alla fine del corso dovresti avere una panoramica delle principali applicazioni quantistiche e un'intuizione del perch\xe9 i computer quantistici potrebbero essere utili in particolari ambiti. Incontrerai tecniche comuni per rappresentare i problemi sui computer quantistici, imparerai come i metodi quantistici e classici lavorano insieme e inizierai a riconoscere quali strumenti e compromessi contano per i diversi tipi di problemi."}),"\n",(0,n.jsx)(e.p,{children:"In questa prima lezione tratteremo alcuni dei concetti fondamentali e della terminologia che aiutano a comprendere ad alto livello le applicazioni del calcolo quantistico, e ti daremo una panoramica delle principali aree applicative che la comunit\xe0 scientifica sta attivamente perseguendo."}),"\n",(0,n.jsx)(e.h2,{id:"what-quantum-computers-might-be-useful-for",children:"A cosa potrebbero servire i computer quantistici"}),"\n",(0,n.jsx)(e.p,{children:"I computer quantistici sono spesso presentati come concorrenti dei computer classici, ma un modo pi\xf9 appropriato di pensarli \xe8 come risorse specializzate all'interno di workflow classici pi\xf9 ampi. La domanda importante, quindi, \xe8 quali parti di un calcolo siano particolarmente adatte all'hardware quantistico. La risposta pi\xf9 intuitiva viene dai problemi che sono gi\xe0 quantistici, come il comportamento di molecole, materiali e campi quantistici. Un processore quantistico pu\xf2 rappresentare e manipolare direttamente gli stati quantistici, mentre le risorse richieste da una descrizione classica generale crescono esponenzialmente con la dimensione del sistema."}),"\n",(0,n.jsx)(e.p,{children:"Il caso \xe8 pi\xf9 sottile per i problemi con input e output classici, ma ci sono comunque buoni motivi per esplorarli. I problemi di ottimizzazione sono molto diffusi ed economicamente importanti, quindi anche un miglioramento modesto della qualit\xe0 della soluzione o del tempo di esecuzione potrebbe essere prezioso. Gli algoritmi quantistici potrebbero inoltre offrire nuovi modi di esplorare spazi di soluzioni complicati o di sfruttare la struttura di particolari classi di problemi. Il machine learning quantistico ha una forte motivazione teorica per certi problemi con input classici, tra cui la classificazione strutturata e l'elaborazione di dataset di grandi dimensioni. Tuttavia, resta una questione aperta se questi risultati possano tradursi in un vantaggio pratico su dati classici del mondo reale. Le equazioni differenziali alle derivate parziali descrivono molti sistemi importanti in scienza, ingegneria e finanza, e gli algoritmi quantistici potrebbero migliorare la scalabilit\xe0 di certe simulazioni ad alta dimensionalit\xe0 e di grandi problemi di algebra lineare."}),"\n",(0,n.jsx)(e.p,{children:"In tutte e tre queste aree, tuttavia, il costo di preparare gli input classici, eseguire il calcolo quantistico ed estrarre una risposta classica utile pu\xf2 superare il beneficio del passaggio quantistico. Terremo presenti queste sfide pratiche mentre esploriamo come i metodi quantistici vengono applicati in ciascuna area."}),"\n",(0,n.jsx)(e.h2,{id:"near-term-quantum-utility-and-advantage",children:"Utilit\xe0 e vantaggio quantistico a breve termine"}),"\n",(0,n.jsx)(e.p,{children:"Questo corso non riguarda specificamente il vantaggio quantistico, ma una discussione sul vantaggio quantistico \xe8 inevitabile. La motivazione fondamentale alla base delle applicazioni quantistiche \xe8 usare risorse quantistiche per estendere ci\xf2 che i computer classici possono fare da soli: produrre risultati pi\xf9 accurati, raggiungere le soluzioni pi\xf9 velocemente o risolvere problemi altrimenti inaccessibili. I seguenti termini correlati ci aiutano a parlare con chiarezza dei progressi che osserviamo:"}),"\n",(0,n.jsxs)(e.ul,{children:["\n",(0,n.jsxs)(e.li,{children:["\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.strong,{children:"Speedup quantistico:"})," Al crescere della dimensione del problema, il tempo richiesto da un metodo quantistico scala in modo pi\xf9 favorevole di quello del miglior metodo classico rilevante per lo stesso compito."]}),"\n"]}),"\n",(0,n.jsxs)(e.li,{children:["\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.strong,{children:"Vantaggio quantistico:"})," Un calcolo abilitato dal quantistico supera i migliori approcci classici rilevanti su un compito ben definito e con una metrica significativa. Pi\xf9 che una pietra miliare singola e permanente, il vantaggio quantistico \xe8 una frontiera in evoluzione che si sposta man mano che migliorano sia i metodi quantistici sia quelli classici."]}),"\n"]}),"\n",(0,n.jsxs)(e.li,{children:["\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.strong,{children:"Utilit\xe0 quantistica:"})," Un calcolo quantistico contribuisce a un risultato scientifico o tecnico utile. Opera a una scala, profondit\xe0 e accuratezza oltre la simulazione classica a forza bruta praticabile, senza necessariamente superare il miglior metodo classico."]}),"\n"]}),"\n",(0,n.jsxs)(e.li,{children:["\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.strong,{children:"Algoritmo a breve termine:"})," Un algoritmo progettato per gli attuali processori quantistici, che usa profondit\xe0 di circuito limitate e spesso si affida al post-processing classico e alla mitigazione degli errori anzich\xe9 alla correzione quantistica degli errori completa."]}),"\n"]}),"\n",(0,n.jsxs)(e.li,{children:["\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.strong,{children:"Calcolo quantistico fault-tolerant:"})," In futuro, il calcolo quantistico user\xe0 la correzione quantistica degli errori per proteggere i qubit logici durante un intero calcolo. Quando i tassi di errore fisici sono sotto la soglia di fault tolerance, risorse aggiuntive di correzione degli errori possono sopprimere gli errori logici al livello richiesto da calcoli lunghi e affidabili. La fault tolerance rende possibili algoritmi molto pi\xf9 profondi, comprese implementazioni su larga scala dell'algoritmo di Shor."]}),"\n"]}),"\n",(0,n.jsxs)(e.li,{children:["\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.strong,{children:"Fault tolerance iniziale:"})," Fault tolerance significa che gli errori vengono soppressi, non eliminati del tutto. Nei primi sistemi fault-tolerant, gli errori logici residui devono comunque essere presi in considerazione e la profondit\xe0 dei circuiti affidabili resta limitata."]}),"\n"]}),"\n",(0,n.jsxs)(e.li,{children:["\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.strong,{children:"Algoritmo euristico:"})," Un metodo progettato per trovare una buona soluzione in pratica, senza garantire la risposta ottimale n\xe9 un particolare tempo di esecuzione."]}),"\n"]}),"\n"]}),"\n",(0,n.jsx)(e.h2,{id:"a-brief-foundation-in-complexity-theory",children:"Una breve introduzione alla teoria della complessit\xe0"}),"\n",(0,n.jsx)(e.p,{children:"In alcune aree applicative abbiamo una solida ragione teorica per aspettarci che un computer quantistico possa avere un vantaggio. Per capire da dove nasce questa fiducia, serve un po' di vocabolario della teoria della complessit\xe0."}),"\n",(0,n.jsx)(e.p,{children:"La teoria della complessit\xe0 studia come crescono le risorse necessarie a risolvere un problema al crescere della sua dimensione. Ci fornisce una mappa utile di dove potrebbe essere possibile uno speedup quantistico. Alcuni termini sono particolarmente importanti per questo corso:"}),"\n",(0,n.jsxs)(e.ul,{children:["\n",(0,n.jsxs)(e.li,{children:["\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.strong,{children:"P:"})," Problemi che un computer classico pu\xf2 risolvere in modo efficiente, cio\xe8 per i quali le risorse richieste crescono in modo polinomiale con la dimensione del problema."]}),"\n"]}),"\n",(0,n.jsxs)(e.li,{children:["\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.strong,{children:"NP:"})," Problemi per i quali si pu\xf2 verificare in modo efficiente una soluzione proposta, anche se trovarla potrebbe essere molto difficile."]}),"\n"]}),"\n",(0,n.jsxs)(e.li,{children:["\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.strong,{children:"NP-hard:"})," Problemi difficili almeno quanto ogni problema in NP. Un problema NP-hard non appartiene necessariamente a NP. Molti problemi di ottimizzazione sono NP-hard."]}),"\n"]}),"\n",(0,n.jsxs)(e.li,{children:["\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.strong,{children:"NP-complete:"})," Problemi che sono sia NP-hard sia in NP. Sono i problemi decisionali pi\xf9 difficili all'interno di NP."]}),"\n"]}),"\n",(0,n.jsxs)(e.li,{children:["\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.strong,{children:"BQP:"})," Problemi che un computer quantistico pu\xf2 risolvere in modo efficiente con una probabilit\xe0 di errore limitata."]}),"\n"]}),"\n"]}),"\n",(0,n.jsx)(e.p,{children:"Alcune relazioni tra queste categorie sono note. P \xe8 contenuto sia in NP sia in BQP, perch\xe9 un problema risolvibile in modo efficiente su un computer classico pu\xf2 anche essere verificato classicamente e risolto su un computer quantistico. Altre relazioni restano aperte. Non sappiamo se P sia uguale a NP o se NP sia contenuto in BQP. Tuttavia, i ricercatori ritengono in generale che P sia pi\xf9 piccolo sia di NP sia di BQP, e che i computer quantistici non possano risolvere in modo efficiente ogni problema NP-complete. In parole semplici, un computer quantistico non \xe8 una scatola magica che risolve istantaneamente ogni problema difficile."}),"\n",(0,n.jsx)(e.p,{children:"Gli argomenti pi\xf9 solidi basati sulla complessit\xe0 a favore del calcolo quantistico valgono per particolari tipi di problemi. L'algoritmo di Shor scala in modo drasticamente migliore dei migliori algoritmi classici noti per la fattorizzazione e i logaritmi discreti, anche se non \xe8 stato dimostrato che la fattorizzazione sia fuori da P. Anche la simulazione quantistica generale ha una solida base teorica. Alcuni problemi di simulazione quantistica sono BQP-complete, il che significa che risolverli efficientemente in modo classico equivarrebbe a simulare efficientemente qualsiasi calcolo quantistico. Una simile simulazione classica efficiente \xe8 altamente implausibile, ed \xe8 uno dei motivi per cui la simulazione hamiltoniana quantistica \xe8 considerata un'area applicativa cos\xec promettente."}),"\n",(0,n.jsx)(e.p,{children:"Alcune PDE ad alta dimensionalit\xe0 possono essere ridotte a problemi di sistemi lineari BQP-complete, il che ci d\xe0 una forte ragione per aspettarci uno speedup quantistico quando input e output possono essere gestiti in modo efficiente. Il QML ha esempi simili: alcuni compiti che coinvolgono dati quantistici sono BQP-complete, e alcuni modelli quantistici possono generare campioni difficili da riprodurre classicamente."}),"\n",(0,n.jsx)(e.p,{children:"Il caso \xe8 meno immediato per l'ottimizzazione. Non ci si aspetta che i computer quantistici risolvano in modo efficiente problemi NP-hard arbitrari, ma potrebbero comunque aiutare con problemi strutturati, istanze particolari o passaggi specifici di un workflow di ottimizzazione. L'algoritmo di Grover, per esempio, fornisce uno speedup quadratico per la ricerca non strutturata. \xc8 un miglioramento significativo, anche se la radice quadrata di uno spazio di ricerca astronomicamente grande pu\xf2 essere ancora astronomica."}),"\n",(0,n.jsx)(e.h2,{id:"from-complexity-theory-to-practical-evidence",children:"Dalla teoria della complessit\xe0 all'evidenza pratica"}),"\n",(0,n.jsx)(e.p,{children:"La teoria della complessit\xe0 pu\xf2 dirci dove potrebbe essere possibile uno speedup quantistico, ma di solito non pu\xf2 dirci come si comporta un metodo su un problema particolare o su un particolare computer quantistico. Molti dei metodi usati sull'hardware attuale sono euristici. Sono progettati per trovare buone risposte in pratica, ma non garantiscono la migliore risposta possibile n\xe9 un particolare tempo di esecuzione."}),"\n",(0,n.jsx)(e.p,{children:"Le euristiche non sono una peculiarit\xe0 del calcolo quantistico, e definire euristico un metodo non significa che sia inaffidabile o non scientifico. L'ottimizzazione classica, il machine learning e la chimica computazionale si affidano pesantemente alle euristiche quando una soluzione esatta sarebbe troppo costosa. Un'euristica quantistica potrebbe offrire un nuovo modo di esplorare uno spazio di soluzioni, preparare stati utili o individuare candidati promettenti. Se funzioni bene \xe8 una questione empirica: dobbiamo eseguirla e misurare il risultato."}),"\n",(0,n.jsx)(e.p,{children:"Poich\xe9 le euristiche non hanno garanzie di prestazioni, le valutiamo usando una metrica di successo chiara, solide baseline classiche e test su diverse dimensioni del problema. Questo ci aiuta a vedere dove un metodo funziona bene e come cambiano le sue prestazioni al crescere del problema."}),"\n",(0,n.jsx)(e.h2,{id:"application-areas-and-course-case-studies",children:"Aree applicative e casi di studio del corso"}),"\n",(0,n.jsx)(e.p,{children:"Organizziamo il corso attorno a quattro ampie aree applicative. Non coprono ogni possibile uso di un computer quantistico, ma ci offrono un modo utile per confrontare dove si trovano gli argomenti pi\xf9 solidi e dove sono le questioni aperte."}),"\n",(0,n.jsx)(e.h3,{id:"hamiltonian-simulation",children:"Simulazione hamiltoniana"}),"\n",(0,n.jsx)(e.p,{children:"La simulazione hamiltoniana comprende la stima di energie, lo studio di propriet\xe0 chimiche e dei materiali e la modellazione di come i sistemi quantistici cambiano nel tempo. Si estende a chimica, scienza dei materiali, fisica della materia condensata e fisica delle alte energie e nucleare. I nostri casi di studio esaminano un modello ferro-zolfo fortemente correlato usando la diagonalizzazione quantistica basata su campioni e simulano la dinamica degli adroni usando una rappresentazione su reticolo che tiene conto delle simmetrie. Sono due esempi di un campo molto pi\xf9 vasto, che comprende anche meccanismi di reazione, materiali magnetici e altre dinamiche a molti corpi."}),"\n",(0,n.jsx)(e.h3,{id:"optimization",children:"Ottimizzazione"}),"\n",(0,n.jsx)(e.p,{children:"L'ottimizzazione compare ovunque, dalla finanza e logistica alla pianificazione e ai sistemi energetici. \xc8 anche un'area in cui il vantaggio \xe8 difficile da stabilire, perch\xe9 i solver classici sono estremamente capaci e le mappature quantistiche possono aggiungere un overhead costoso. Il nostro caso di studio usa la selezione di portafoglio per esplorare come un problema di ottimizzazione viene rappresentato, eseguito e sottoposto a benchmark, senza presumere che un computer quantistico trovi automaticamente l'ottimo esatto."}),"\n",(0,n.jsx)(e.h3,{id:"quantum-machine-learning",children:"Machine learning quantistico"}),"\n",(0,n.jsx)(e.p,{children:"Il machine learning quantistico si chiede se i circuiti quantistici o i dati quantistici possano migliorare un compito di apprendimento. Tra le questioni importanti ci sono la codifica dei dati, il costo dell'addestramento, la generalizzazione e il confronto con solidi modelli classici."}),"\n",(0,n.jsx)(e.h3,{id:"partial-differential-equations",children:"Equazioni differenziali alle derivate parziali"}),"\n",(0,n.jsx)(e.p,{children:"Le equazioni differenziali alle derivate parziali descrivono sistemi come fluidi, calore e onde. Gli algoritmi quantistici potrebbero accelerare parti di alcuni workflow PDE, ma la preparazione dei dati e l'estrazione di una risposta classica utile possono essere costi rilevanti. Il caso di studio specifico \xe8 ancora in fase di sviluppo."}),"\n",(0,n.jsx)(e.p,{children:"Nelle lezioni seguenti porremo le stesse domande di base in ogni area: qual \xe8 il problema, perch\xe9 il calcolo quantistico potrebbe aiutare, quali sono i limiti e cosa mostrano davvero le evidenze? Inizieremo dalla simulazione hamiltoniana, dove il problema stesso \xe8 quantistico."}),"\n",(0,n.jsx)(e.h2,{id:"conclusion",children:"Conclusione"}),"\n",(0,n.jsx)(e.p,{children:"Abbiamo coperto molto terreno, ma l'idea principale \xe8 semplice: i computer quantistici sono strumenti specializzati e il loro valore dipende dall'uso del metodo quantistico giusto per il problema giusto o per la parte giusta di un problema pi\xf9 grande. La simulazione hamiltoniana ha le basi teoriche pi\xf9 chiare, l'ottimizzazione dispone di un insieme maturo di metodi euristici e benchmark, mentre QML e PDE offrono direzioni promettenti ancora in sviluppo."}),"\n",(0,n.jsx)(e.p,{children:"Nelle lezioni seguenti passeremo da questa ampia panoramica a esempi pratici. Per ogni applicazione ci chiederemo quale problema stiamo cercando di risolvere, che ruolo svolge il computer quantistico, come viene interpretato il risultato e cosa possiamo imparare da esso. L'obiettivo \xe8 costruire la tua intuizione su dove il calcolo quantistico potrebbe aiutare e su cosa serve per trasformare un'idea promettente in un calcolo reale."}),"\n"]})}function p(i={}){const{wrapper:e}={...(0,t.R)(),...i.components};return e?(0,n.jsx)(e,{...i,children:(0,n.jsx)(u,{...i})}):u(i)}},28453(i,e,a){a.d(e,{R:()=>r,x:()=>s});var o=a(96540);const n={},t=o.createContext(n);function r(i){const e=o.useContext(t);return o.useMemo(function(){return"function"==typeof i?i(e):{...e,...i}},[e,i])}function s(i){let e;return e=i.disableParentContext?"function"==typeof i.components?i.components(n):i.components||n:r(i.components),o.createElement(t.Provider,{value:e},i.children)}}}]);